function dashBase(){const f=filters.dash;return (data?.asignaciones||[]).filter(r=>r.estado!=='Anulado'&&(!f.from||r.inicio>=f.from)&&(!f.to||r.inicio<=f.to)&&(!f.mode||mode(r)===f.mode)&&(!f.unit||unit(r)===f.unit));}
