function makeDraft(r){return {record:r,checklist:Object.fromEntries(r.checklist.map(c=>[c.id,{resultado:c.resultado,observacion:c.observacion}])),metrado:{...r.metrado},fechaInspeccion:r.fechaInspeccion||'',observacionTecnica:r.observacionTecnica||''};}
function draftComplete(){return !!draft&&draft.record.checklist.length>0&&draft.record.checklist.every(c=>draft.checklist[c.id].resultado==='Conforme');}
function draftValid(){return draftComplete()&&meters.every(([k],i)=>{const v=txt(draft.metrado[k]).trim();return /^\d+(\.\d+)?$/.test(v)&&Number(v)<=100000000&&([0,4].includes(i)||Number.isInteger(Number(v)));})&&draft.fechaInspeccion>=draft.record.inicio&&draft.fechaInspeccion<=data.hoy;}
