function notices(rs){const alerts=rs.filter(r=>r.estado!=='Anulado'&&(r.estado==='Asignado'||r.estado==='Observado'||r.estado==='Conforme'||(!timing(r).presented&&timing(r).delta<=2)));if(!alerts.length)return '';return `<details class="hdi-details"><summary>${data.admin?'Alertas de inspecciones':'Alertas de mis inspecciones'} (${alerts.length})</summary><div class="hdi-notice-list">${alerts.slice(0,30).map(r=>`<button type="button" data-hdi-act="notice" data-id="${esc(r.id)}"><i class="fa-solid ${r.estado==='Conforme'?'fa-check-circle':r.estado==='Observado'?'fa-exclamation-circle':r.estado==='Asignado'?'fa-clipboard-list':'fa-clock'}"></i> ${esc(label(r))} · ${esc(r.estado==='Conforme'?'Inspección aprobada':r.estado==='Observado'?'Observación del supervisor':r.estado==='Asignado'?'Asignación pendiente de iniciar':timing(r).condition)}${!timing(r).presented?' · '+esc(timing(r).condition):''}</button>`).join('')}</div>${alerts.length>30?'<p class="hdi-muted">Se muestran las primeras 30 alertas; consulta todos los expedientes en la bandeja.</p>':''}</details>`;}
function renderMine(){const f=filters.mine,rs=currentList(),p=page(rs,f),mine=data.asignaciones.filter(r=>data.admin||r.responsable===data.usuario),r=mine.find(x=>x.id===detailId);return panel(data.admin?'Inspecciones asignadas — administración':'Mis inspecciones asignadas',`<div class="hdi-metrics">${['all','done','pending','late'].map(k=>metric(k,mine.filter(r=>hasKind(r,k)).length,'mine-kind',f.kind===k)).join('')}</div>${notices(mine)}<div class="hdi-filters">${fld('Buscar',inp('hdiQuery',f.q,'Ítem, sector, solicitud…'))}${fld('Actividad',sel('hdiStage',[['','Todas'],...stages.map(x=>[x,x])],f.stage))}${fld('Estado del trabajo',sel('hdiKind',[...kinds.map(([k,l])=>[k,l]),['cancel','Anulados']],f.kind))}${button('filter','Buscar','hdi-outline')}${button('export','<i class="fa-solid fa-file-excel"></i> Excel','hdi-outline')}</div>${table(['Ítem','Sector',...(data.admin?['Responsable']:[]),'Actividad pendiente','Checklist','Derivación','Fecha máxima','Plazo','Acción'],p.rs.map((r,i)=>row([esc(f.page*25+i+1),esc(sector(r)),...(data.admin?[esc(r.nombre)]:[]),esc(stage(r)),esc(countCheck(r)+'/'+r.checklist.length),esc(fmt(r.inicio)),esc(fmt(r.limite)),badge(timing(r).condition,timing(r).excess>0),button('detail',canEdit(r)?'Trabajar':'Consultar','hdi-outline',`data-id="${esc(r.id)}"`)])))}${p.foot}`)+(r?renderInspection(r):'');}
function history(r){return `<details class="hdi-details"><summary>Historial de derivaciones y operaciones (${r.historial.length})</summary>${r.historial.map(h=>`<div class="hdi-history"><b>${esc(h.accion)}</b> · ${esc(h.fecha)} · ${esc(h.usuario)}<br>${esc(typeof h.detalle==='object'?JSON.stringify(h.detalle):h.detalle)}</div>`).join('')}</details>`;}
function readDetail(r){const t=timing(r);return panel(label(r),`<div class="hdi-info"><b>${esc(r.nombre)}</b><span>${esc(stage(r))}</span><span>${esc(fmt(r.inicio))} → ${esc(fmt(r.limite))}</span>${badge(t.condition,t.excess>0)}</div>${registration(r)}<h4>Checklist aplicado</h4>${table(['N.º','Requisito','Resultado','Observación'],r.checklist.map(c=>row([esc(c.orden),esc(c.texto),esc(c.resultado||'Sin evaluar'),esc(c.observacion)])))}<h4>Metrados</h4><dl class="hdi-meters">${meters.map(([k,l])=>`<div><dt>${esc(l)}</dt><dd>${esc(r.metrado[k]??'—')}</dd></div>`).join('')}</dl><p><b>Fecha de inspección:</b> ${esc(fmt(r.fechaInspeccion))} · <b>Presentación:</b> ${esc(fmt(r.presentacion))} · <b>Conformidad:</b> ${esc(fmt(r.conformidad))}</p><p><b>Observaciones técnicas:</b> ${esc(r.observacionTecnica||'—')}</p><p><b>Observaciones del supervisor:</b> ${esc(r.observacion||'—')}</p>${documentList(r.adjuntos,'evidence')}${history(r)}${button('close-detail','Cerrar detalle','hdi-outline')}`);}
function renderSuper(){const f=filters.super,rs=currentList(),p=page(rs,f),r=data.asignaciones.find(x=>x.id===detailId),chosen=data.asignaciones.filter(x=>supPick.has(x.id)),canSuper=chosen.length>0&&chosen.every(x=>!['Conforme','Anulado'].includes(x.estado)),canReturn=canSuper,canApprove=canSuper&&chosen.every(x=>x.estado==='Por revisar'),canChange=canSuper&&chosen.every(x=>x.estado!=='Por revisar');return panel('Seguimiento y supervisión',`<div class="hdi-filters">${fld('Responsable',sel('hdiPerson',personOptions(),f.person))}${fld('Estado',sel('hdiState',[['','Todos'],...states.map(x=>[x,x])],f.state))}${fld('Actividad',sel('hdiStage',[['','Todas'],...stages.map(x=>[x,x])],f.stage))}${fld('Buscar',inp('hdiQuery',f.q,'Ítem, sector…'))}${button('filter','Buscar','hdi-outline')}${button('export','<i class="fa-solid fa-file-excel"></i> Excel','hdi-outline')}</div><label class="hdi-check"><input type="checkbox" data-hdi-all="super" ${rs.length&&rs.every(r=>supPick.has(r.id))?'checked':''}> Seleccionar todos (${rs.length}) · ${supPick.size} seleccionados</label>${table(['Elegir','Ítem','Sector','Responsable','Estado / actividad','Checklist','Fecha máxima','Plazo','Consulta'],p.rs.map(r=>row([`<input type="checkbox" data-hdi-pick="super" data-id="${esc(r.id)}" ${supPick.has(r.id)?'checked':''}>`,esc(item(r)),esc(sector(r)),esc(r.nombre),esc(r.estado+' / '+stage(r)),esc(countCheck(r)+'/'+r.checklist.length),esc(fmt(r.limite)),badge(timing(r).condition,timing(r).excess>0),button('detail','<i class="fa-regular fa-eye"></i>','hdi-outline',`data-id="${esc(r.id)}"`)])))}${p.foot}`)+(r?readDetail(r):'')+panel('Operaciones individuales o masivas',`${fld('Motivo u observaciones del supervisor',`<textarea id="hdiReason" rows="3" maxlength="3000">${esc(form.reason)}</textarea>`)}<div class="hdi-actions">${button('super','Dar conformidad','',`data-op="aprobar" ${canApprove?'':'disabled'}`)}${button('super','Registrar observaciones','hdi-outline',`data-op="observar" ${canReturn?'':'disabled'}`)}${button('super','Anular derivación','hdi-danger',`data-op="anular" ${canChange?'':'disabled'}`)}</div><div class="hdi-filters">${fld('Nuevo responsable',sel('hdiNewPerson',[['','Seleccionar…'],...staffOptions()],form.newPerson))}${button('super','Reasignar','hdi-outline',`data-op="reasignar" ${canChange?'':'disabled'}`)}${fld('Nueva fecha máxima',inp('hdiNewDue',form.newDue||data.hoy,'','date',`min="${esc(data.hoy)}"`))}${button('super','Ampliar plazo','hdi-outline',`data-op="ampliar" ${canChange?'':'disabled'}`)}</div><p class="hdi-muted">Se valida todo el lote antes de modificarlo. Las aprobaciones no sobrescriben datos operativos existentes en OM5.</p>`);}
function metric(k,n,a,selected=false){return `<button type="button" class="hdi-metric ${selected?'hdi-metric-active':''}" data-hdi-act="${a}" data-kind="${k}"><small>${esc(kinds.find(x=>x[0]===k)?.[1]||k)}</small><strong class="${['late','delayed'].includes(k)?'hdi-red':''}">${n}</strong></button>`;}
function dashSummaryTable(headers,rows){return table(headers,rows).replace('class="hdi-table-wrap"','class="hdi-table-wrap" style="max-height:none"');}
function renderDash(){const f=filters.dash,all=dashBase(),people=personOptions(false).filter(([id])=>all.some(r=>r.responsable===id)),count=(p,k)=>all.filter(r=>(!p||r.responsable===p)&&hasKind(r,k)).length,rs=currentList(),p=page(rs,f),r=rs.find(x=>x.id===detailId),click=(p,k)=>button('dash-select',String(count(p,k)),'hdi-link',`data-person="${esc(p)}" data-kind="${k}"`),persons=[...people,['','TOTAL']];return panel('Control de productividad y cumplimiento',`<div class="hdi-filters">${fld('Fecha de inicio',inp('hdiDashFrom',f.from,'','date'))}${fld('Fecha de fin',inp('hdiDashTo',f.to,'','date'))}${fld('Modalidad',sel('hdiDashMode',modalities(data.asignaciones),f.mode))}${fld('Unidad empresarial (UUEE)',sel('hdiDashUnit',units(data.asignaciones),f.unit))}${button('dash-filter','Aplicar filtros','')}${button('dash-clear','Limpiar filtros','hdi-outline')}</div><p class="hdi-muted">Período según fecha de derivación, inclusive. Personal con asignaciones: ${people.length}.</p><div class="hdi-metrics">${kinds.map(([k])=>metric(k,count('',k),'dash-select',!f.person&&f.kind===k)).join('')}</div><h3>Seguimiento por responsable</h3>${dashSummaryTable(['Responsable','Asignados','Atendidos','Pendientes','Vencidos'],persons.map(([id,n])=>row([`<b>${esc(n)}</b>`,...['all','done','pending','late'].map(k=>click(id,k))])))}<h3>Cumplimiento de plazos</h3>${dashSummaryTable(['Responsable','Atendidos a tiempo','Atendidos con atraso','Cumplimiento','Avance'],persons.map(([id,n])=>row([`<b>${esc(n)}</b>`,click(id,'timely'),click(id,'delayed'),count(id,'done')?(count(id,'timely')/count(id,'done')*100).toFixed(1)+'%':'—',count(id,'all')?(count(id,'done')/count(id,'all')*100).toFixed(1)+'%':'—'])))}<p class="hdi-muted">Pulsa cualquier cantidad, incluida la fila TOTAL, para consultar y exportar sus expedientes.</p>`)+panel('Detalle: '+(f.person?people.find(x=>x[0]===f.person)?.[1]||f.person:'TOTAL')+' — '+(kinds.find(x=>x[0]===f.kind)?.[1]||''),`<div class="hdi-filters">${fld('Buscar',inp('hdiQuery',f.q,'Ítem, sector, solicitud…'))}${fld('Actividad pendiente',sel('hdiStage',[['','Todas'],...stages.map(x=>[x,x])],f.stage))}${fld('Responsable en detalle',sel('hdiDetailPerson',f.person?[['','Responsable seleccionado'],...people.filter(x=>x[0]===f.person)]:[['','Todos'],...people],f.detailPerson))}${button('filter','Buscar','hdi-outline')}${button('export','<i class="fa-solid fa-file-excel"></i> Exportar Excel ('+rs.length+')','',rs.length?'':'disabled')}</div>${table(['Ítem','Sector','Responsable','Derivación','Fecha límite','Actividad pendiente','Checklist','Días restantes','Días exceso','Consulta'],p.rs.map((r,i)=>{const t=timing(r);return row([esc(f.page*25+i+1),esc(sector(r)),esc(r.nombre),esc(fmt(r.inicio)),esc(fmt(r.limite)),esc(stage(r)),esc(countCheck(r)+'/'+r.checklist.length),esc(t.remaining),t.excess?`<b class="hdi-red">${t.excess}</b>`:'0',button('detail','<i class="fa-regular fa-eye"></i>','hdi-outline',`data-id="${esc(r.id)}"`)]);}))}${p.foot}`)+(r?readDetail(r):'');}
function render(){const el=root();if(!el)return;if(!data){el.innerHTML='<div class="hdi-panel hdi-muted">Consultando inspecciones OM5…</div>';return;}if(activePage==='dash'){el.innerHTML=renderDash();return;}if(view==='derive'&&!data.supervisor||view==='super'&&!data.supervisor)view=data.supervisor?'super':'mine';el.innerHTML=navigation()+(view==='derive'?renderDerive():view==='super'?renderSuper():renderMine());}
async function request(action,d={},extra={}){const t=token(),g=generation;if(!allowed()||!t)throw Error('Sesión requerida.');const result=await window.postGateway({action,datos:JSON.stringify(d),...extra},120000);if(t!==token()||g!==generation)throw Error('La sesión o la consulta cambió.');return result;}
async function load(){if(!allowed())return;if(ownerToken&&ownerToken!==token())reset();ownerToken=token();const g=++generation,t=token();setBusy(true);message('Consultando datos de inspecciones OM5…');try{const r=await window.postGateway({action:'amplInspRead'},120000);if(g!==generation||t!==token())return;if(!['REV142','REV144','REV158'].includes(r.revision)||!Array.isArray(r.asignaciones)||!Array.isArray(r.disponibles))throw Error('El backend publicado no incluye la revisión de inspecciones.');data=r;message('Datos actualizados · '+fmt(data.hoy));render();}catch(e){if(g===generation&&t===token()){data=null;root().innerHTML='<div class="hdi-panel hdi-muted">No se pudo cargar el módulo. Pulsa Actualizar.</div>';message(e.message,true);}}finally{if(g===generation)setBusy(false);}}
async function enter(pageName){if(busy)return;if(!allowed()||pageName==='dash'&&!supervisor())return;if(ownerToken&&ownerToken!==token())reset();activePage=pageName;const other=$(pageName==='dash'?'hdiOpsBody':'hdiDashBody');if(other)other.replaceChildren();if(pageName==='ops'&&!data)view=admin()?'derive':supervisor()?'super':'mine';if(data){render();message(status,statusError);}else render();if(!dirty)await load();}
async function mutate(action,d,extra={}){if(busy)return false;setBusy(true);const t=token(),g=generation;message('Procesando operación…');try{const r=await request(action,d,extra);if(t!==token()||g!==generation)return false;dirty=false;draft=null;message('Operación registrada correctamente.');setBusy(false);await load();if(t===token()){if(data)message('Operación registrada correctamente.');else message('Operación registrada. No se pudo recargar el listado; pulsa Actualizar antes de repetir.',true);}return !!r.success;}catch(e){if(t===token()&&g===generation)message(e.message+(e.respuestaServidor?'':' Verifica el historial antes de repetir una operación cuya respuesta no llegó.'),true);return false;}finally{if(t===token())setBusy(false);}}
function savePayload(r){if(!draft||draft.record.id!==r.id)throw Error('Selecciona una inspección.');if(r.checklist.some(c=>draft.checklist[c.id].resultado==='Observado'&&!txt(draft.checklist[c.id].observacion).trim()))throw Error('Indica las observaciones de todos los requisitos observados.');return {id:r.id,version:r.version,checklist:draft.checklist,...(draftComplete()?{metrado:draft.metrado,fechaInspeccion:draft.fechaInspeccion,observacionTecnica:draft.observacionTecnica}:{})};}
async function save(submit){if(!draft||!canEdit(draft.record))return;if(submit&&!draftValid())throw Error('Completa el checklist, metrados y fecha de inspección.');if(submit&&!confirm('¿Presentar la inspección para revisión? Quedará bloqueada hasta la respuesta del supervisor.'))return;await mutate(submit?'amplInspSubmit':'amplInspSave',savePayload(draft.record));}
